        raise FileNotFoundError(directory)

    zip_path = os.path.join(directory, 'files.zip')
    files = [
        path
        for path in glob.glob(
            os.path.join(glob.escape(directory), '*'), include_hidden=True
        )
        if os.path.isfile(path)
        and os.path.abspath(path) != os.path.abspath(zip_path)
    ]
    if not files:
        return None

