import os
import glob

DIRECTORY = 'data'


def task_func(directory):
    """Read dictionary literals from the directory's text files."""
    dictionaries = []
    pattern = os.path.join(glob.escape(os.fspath(directory)), '*.txt')
    for filename in glob.glob(pattern):
        with open(filename, 'r', encoding='utf-8') as file:
            content = file.read()
        try:
            value = ast.literal_eval(content)
        except (SyntaxError, ValueError) as exc:
            raise ValueError(
