import pandas as pd
import random
import re


def task_func(data_list, seed=None):
    """Apply one randomly selected substring operation to each input string."""
    if seed is not None:
        random.seed(seed)

    modified_strings = []
    for original in data_list:
        # A single space following a comma is separator formatting; any
        # additional whitespace remains part of the substring.
        separator = ', ' if ', ' in original else ','
        substrings = re.split(re.escape(separator), original)
        operation = random.choice(['remove', 'replace', 'shuffle', 'randomize'])

        if operation == 'remove':
            if len(substrings) > 1:
                substrings.remove(random.choice(substrings))
        elif operation == 'replace':
            index = random.randrange(len(substrings))
            substrings[index] = 'random_string'
        elif operation == 'shuffle':
            random.shuffle(substrings)
        else:
            substrings = random.sample(substrings, len(substrings))

        modified_strings.append(separator.join(substrings))

    return pd.DataFrame({
        'Original String': data_list,
        'Modified String': modified_strings,
    })

