import random
import string

POSSIBLE_LETTERS = ['a', 'b', 'c']


def task_func(word):
    """Return randomly selected adjacent letter pairs from word."""
    if any(letter not in string.ascii_letters for letter in word):
        raise ValueError('The input must contain only letters.')

    if len(word) < 2:
        return ['' for _ in POSSIBLE_LETTERS]

    return [
        word[start:start + 2]
        for start in (
            random.randrange(len(word) - 1) for _ in POSSIBLE_LETTERS
        )
    ]

