from operator import itemgetter
import itertools


ANIMAL = ['cat', 'camel', 'cow', 'dog', 'elephant', 'fox', 'giraffe', 'hippo', 'iguana', 'jaguar']


def task_func(animal_dict):
    """Remove invalid animal keys and count letters in the remaining names."""
    for animal in list(animal_dict):
        if animal not in ANIMAL:
            del animal_dict[animal]

    counts = Counter(itertools.chain.from_iterable(animal_dict))
    return dict(sorted(counts.items(), key=itemgetter(1), reverse=True))

