import os
import random
import pandas as pd


def task_func(data_dir,
              csv_files=['file1.csv', 'file2.csv', 'file3.csv'],
              seed=None):
    """Select a CSV and sample a random number of its rows without replacement."""
    random.seed(seed)
    file_name = random.choice(csv_files)
    file_path = os.path.join(data_dir, file_name)

    try:
        data = pd.read_csv(file_path)
    except pd.errors.EmptyDataError:
        return file_name, pd.DataFrame()

    if data.empty:
        return file_name, data

    number_of_rows = random.randint(1, len(data))
    return file_name, data.sample(n=number_of_rows, random_state=seed)

