import itertools


def task_func(n_walks, n_steps, seed=None):
    """Generate and plot random walks with symmetric steps of -1 or 1."""
    for name, value in (("n_walks", n_walks), ("n_steps", n_steps)):
        if not isinstance(value, (int, np.integer)):
            raise TypeError(f"{name} must be an integer")
        if value <= 0:
