import random
import re


def task_func(text, seed=None):
    """Scramble word interiors, preserving first and last characters."""
    if seed is not None:
        random.seed(seed)

    def scramble(match):
        word = match.group(0)
        if len(word) <= 3:
            return word
        interior = list(word[1:-1])
        random.shuffle(interior)
        return word[0] + ''.join(interior) + word[-1]

    return re.sub(r'\b\w+\b', scramble, text)

