import os
import ssl
import hashlib
import tempfile
from contextlib import contextmanager


class ProbeSocket:
    def __init__(self, request=b'', failure=None):
        self.remaining = request
        self.failure = failure
        self.recv_sizes = []
        self.sent = bytearray()
        self.closed = False

    def recv(self, size, *args, **kwargs):
        self.recv_sizes.append(size)
        if self.failure is not None:
            raise self.failure
        part = self.remaining[:size]
        self.remaining = self.remaining[size:]
        return part

    def send(self, data, *args, **kwargs):
        self.sent.extend(data)
        return len(data)

    def sendall(self, data, *args, **kwargs):
        self.sent.extend(data)

    def write(self, data):
        return self.send(data)

    def close(self):
        self.closed = True

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()
        return False


@contextmanager
def simulated_tls(raw, secure):
    # Substitute only the TLS boundary; use real files and real SHA256.
    wrapped = []

    def wrap(sock=None, *args, **kwargs):
        if sock is None:
            sock = kwargs.get('socket')
        wrapped.append(sock)
        return secure

    class Context:
        def __init__(self, *args, **kwargs):
            pass

        def load_cert_chain(self, *args, **kwargs):
            pass

        def wrap_socket(self, sock=None, *args, **kwargs):
            return wrap(sock, *args, **kwargs)

    replacements = {
        'wrap_socket': wrap,
        'SSLContext': Context,
        'create_default_context': lambda *args, **kwargs: Context(),
    }
