import numpy as np
import pandas as pd
import statistics


def task_func(rows, columns=['A', 'B', 'C', 'D', 'E', 'F'], seed=42):
    """Return seeded random integer data and each column's mean and median."""
    if (
        isinstance(rows, (bool, np.bool_))
        or not isinstance(rows, (int, np.integer))
        or rows <= 0
    ):
        raise ValueError('rows must be a positive integer greater than 0')

    np.random.seed(seed)
    data = np.random.randint(1, 101, size=(rows, len(columns)))
    df = pd.DataFrame(data, columns=columns)

    stats = {}
    for column in columns:
        values = df[column].tolist()
        stats[column] = {
            'mean': statistics.mean(values),
            'median': statistics.median(values),
        }

    return df, stats

