import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    """Reverse matching words in each cell, leaving nonmatching words in place."""
    result = df.copy()
    if pattern == "":
        return result

    expression = re.compile(pattern)

    def reverse_matching_words(text: str) -> str:
        words = text.split()
        positions = [
            index for index, word in enumerate(words)
            if expression.match(word) is not None
        ]
        replacements = [words[index] for index in reversed(positions)]
        for index, word in zip(positions, replacements):
            words[index] = word
        return " ".join(words)

    result[column_name] = result[column_name].apply(reverse_matching_words)
    return result

