from itertools import combinations


def task_func(array1, array2):
    """Return the maximum Euclidean distance between index-paired points.

    Points are (array1[i], array2[i]), as established by the example.
    Unequal lengths raise ValueError. With fewer than two points, return 0.0.
    """
