    except Exception as exc:
        errors.append(str(exc))
        return backup_dir, errors

    try:
        entries = os.listdir(directory)
    except Exception as exc:
        errors.append(str(exc))
        return backup_dir, errors

    for entry in entries:
        path = os.path.join(directory, entry)
        try:
            if os.path.isdir(path) and not os.path.islink(path):
                shutil.rmtree(path)
            else:
                os.unlink(path)
        except Exception as exc:
